# Exhaustive path check on small numbers of cut sequences, with independent costs.
def exhaustive(fib,caps,stride):
  S=len(caps);best=None;bestcuts=None;count=0
  def rec(i,b,cuts,peak):
    nonlocal best,bestcuts,count
    if i==S:
      if b==128:
        count+=1
        if best is None or peak<best:best,bestcuts=peak,cuts[:]
